package serverviwe.view.controller;
import jakarta.servlet.http.HttpSession;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import serverviwe.view.model.ProjectDeployed;import serverviwe.view.model.ServerInfo;import serverviwe.view.reposiotory.ProjectDeployedRepository;import serverviwe.view.reposiotory.ServerInfoRepository;import java.util.*;
@Controller @RequiredArgsConstructor public class ProjectController {private final ProjectDeployedRepository projects;private final ServerInfoRepository servers;
@GetMapping("/projects") public String list(HttpSession s,Model m){String h=(String)s.getAttribute("host");if(h==null)return "redirect:/connecttovps";Integer port=(Integer)s.getAttribute("port");servers.findByServerIpAndSshPort(h,port).ifPresent(x->m.addAttribute("projects",projects.findByServerInfoId(x.getId())));if(!m.containsAttribute("projects"))m.addAttribute("projects",List.of());return "projects";}
@PostMapping("/projects") public String save(@RequestParam String name,@RequestParam(required=false)String path,@RequestParam(defaultValue="DEPLOYED")ProjectDeployed.ProjectStatus status,HttpSession s){String h=(String)s.getAttribute("host");Integer port=(Integer)s.getAttribute("port");ServerInfo server=servers.findByServerIpAndSshPort(h,port).orElseThrow();ProjectDeployed p=new ProjectDeployed();p.setServerInfo(server);p.setProjectName(name.trim());p.setProjectPath(path);p.setStatus(status);projects.save(p);return "redirect:/projects";}
@PostMapping("/projects/delete") public String delete(@RequestParam Long id){projects.deleteById(id);return "redirect:/projects";}}
